insert into public.articles (id, slug, titre, categorie, date_affichee, date_publication, resume, corps, image, image_alt, service, lien_externe, exemple, ordre, publie) values ('a-deconstruction', 'deconstruction-reconstruction-des-infrastructures', 'Déconstruction-reconstruction des infrastructures', 'Actualité', '2024', null, 'Un plan soutenu par le Plan de Relance pour améliorer durablement l’accueil.', '', '', '', null, '', true, 5, true) on conflict (id) do nothing;
